from common import *
import re
def main():
    out=ROOT/'results/lsc/r61_analysis';audit=load(out/'verification.json');visual=load(out/'visual_review.json');assert audit['complete'] and visual['passed'];key=load(out/'key_results.json');pub=load(out/'published.json');rel=Path(pub['report']['path']).relative_to(REPO).as_posix()
    def row(model,kind):return next(x for x in key['tables'] if x['view']=='nominal_all30' and x['model']==model and x['kind']==kind)
    a,b=row('Raw','adjacent'),row('R61','adjacent');c,d=row('Raw','start'),row('R61','start')
    text=f'**R136 LSC先行結果（2026-09-16）：** 改用論文LSC圓心定位；原圖／R61各930張、8370圓心全部完成。9圓合併每步平均絕對PI差距{a["mae_nm"]:.3f}→{b["mae_nm"]:.3f}nm，起點相對{c["mae_nm"]:.3f}→{d["mae_nm"]:.3f}nm；30次中短步30次改善、長距離24次改善。逐顆9圓均改善。舊影像區域比對是另一讀法，另存補充，不混稱LSC。R129重建與LSC續跑，無模型升級。[LSC報告]({rel})'
    p=REPO/'PROJECT_STATE.md';s=p.read_text(encoding='utf-8-sig');s=re.sub(r'(?m)^\*\*R136先行結果.*$',text,s);s=s.replace('### R136 原圖與R61先行比較','### R136 LSC圓心位移比較');s=re.sub(r'(?m)^Last updated:.*$','Last updated: 2026-09-16（R136已改用論文LSC完成原圖與R61；影像區域比對另列補充，R129續跑）',s,count=1);p.write_text(s,encoding='utf-8')
    p=REPO/'ESTIMATOR_POLICY.json';policy=load(p);baseline=policy['formal_baseline'];entry=next(x for x in policy['open_side_tracks'] if x.get('candidate_id')=='r136_pi_repeatability')
    if 'phase_correlation_supplement' not in entry:entry['phase_correlation_supplement']={k:entry[k] for k in ['report','main_results','intensity_reader'] if k in entry}
    entry.pop('intensity_reader',None);entry.update(status='lsc_raw_r61_complete_r129_running',method='thesis_inflection_LSC_center9_median',report=rel,centers_per_model=8370,main_results=key['tables'],comparisons=key['comparisons'],notes='Primary uses actual circle centers from thesis LSC. Prior phase-region readout remains separate supplementary evidence. Same sample/session,not universal scene or full uncertainty certification. R129 continues.');assert policy['formal_baseline']==baseline;save(p,policy)
    p=REPO/'Experiments/INDEX.md';s=p.read_text(encoding='utf-8-sig');line=f'| R136 PI重拍比較 | [LSC原圖／R61](R136_PIRepeatability/reports/R136_LSC_R61_RESULTS.md) | 各8370圓心；短步{a["mae_nm"]:.3f}→{b["mae_nm"]:.3f}nm，長距離{c["mae_nm"]:.3f}→{d["mae_nm"]:.3f}nm；舊區域比對另存，R129續跑 |';s=re.sub(r'(?m)^\| R136 PI重拍比較 \|.*$',line,s);p.write_text(s,encoding='utf-8')
    p=ROOT/'README.md';s=p.read_text(encoding='utf-8');notice='\n**主結果已改用論文LSC圓心定位：[原圖／R61完整結果](reports/R136_LSC_R61_RESULTS.md)。先前區域影像比對只作補充，不能與LSC數字混用。**\n';s=s.replace('\n', '\n'+notice,1);p.write_text(s,encoding='utf-8')
    # Clarify the earlier report without changing any earlier numerical results.
    p=ROOT/'reports/R136_R61_RESULTS.md';s=p.read_text(encoding='utf-8');notice='\n> 方法說明：本份使用影像區域比對，不是LSC圓心定位。論文LSC主結果請見[LSC完整比較](R136_LSC_R61_RESULTS.md)。\n'
    if '> 方法說明：本份使用影像區域比對' not in s:s=s.replace('\n','\n'+notice,1);p.write_text(s,encoding='utf-8')
    for name in ['published.json','delivery_complete.json']:
        q=ROOT/'results/r61_analysis'/name;data=load(q);data['report']=record(p);data['method_notice_added_utc']=now();save(q,data)
    with (ROOT/'MANIFEST.md').open('a',encoding='utf-8') as f:f.write('\nPrimary method correction: thesis LSC,9sharedcircles/frame; Raw/R61 each8370centers completed,independent circle fitting verified. reports/R136_LSC_R61_RESULTS.md and results/lsc/r61_analysis are current. Prior phase reports remain supplementary. R129 whole-task status still running.\n')
    with (ROOT/'HANDOFF.md').open('a',encoding='utf-8') as f:f.write('\n## LSC Raw/R61 delivered; full three-model LSC remains active\n\nPrimary report reports/R136_LSC_R61_RESULTS.md; results/lsc/r61_analysis/tables; visual and16740independent circle-fit checks complete. Raw/R61 median9 shortMAE8.667306/5.160403nm,repeatSD10.451826/5.194955; startMAE17.738028/15.267412,repeatSD14.796490/11.870377. Short30/30scans improve; start24/30. All9individual circles improve both mean errors. Old phase report explicitly labeled supplementary.\n\nRunning scripts: reconstruct.py R129; lsc_measure.py --workers4 consumes all completed scans; lsc_finish_when_ready.py waits for results/lsc/complete.json then runs analyze.py with --input results/lsc/readouts --primary-roi center9 --primary-reader LSC --out results/lsc/analysis/tables, lsc_details.py and lsc_publish.py. Observe results/lsc/status.json and results/lsc/delivery_status.json; old status_measurements and old finisher no longer govern work. At ready, view reports/lsc_figures,check reports/R136_LSC_RESULTS.md and verification,update existing R136 registration to full3-model completion,mark overall marker complete,and pause automation r136 after delivery. Full-data publisher supports modelsRaw/R61/R129; avoid calling old phase publish.py as main.\n')
    p=REPO/'docs/operations/PROJECT_STORAGE_REGISTRY.json';reg=load(p);e=next(x for x in reg['entries'] if x.get('id')=='r136_pi_repeatability');e.update(state='lsc_raw_r61_complete_r129_running',report=rel);reg['updated_at']=now();save(p,reg)
    save(out/'delivery_complete.json',dict(report=pub['report'],figures=pub['figures'],verification=record(out/'verification.json'),visual_review=record(out/'visual_review.json'),centers_per_model=8370,models=['Raw','R61'],R129_active=True,completed_utc=now()));print('LSC Raw/R61 registered; R129 continues',flush=True)
if __name__=='__main__':main()
